import { createHttp } from '@pyreon/http'
import { createMock } from '@pyreon/http/mock'
import { openEventStream } from '@pyreon/http/stream'

const sse = 'event: token\ndata: {"text":"Hel"}\n\nevent: token\ndata: {"text":"lo"}\n\nevent: done\ndata: {}\n\n'
const mock = createMock([
  { method: 'POST', path: '/chat', accept: 'text/event-stream', headers: { 'content-type': 'text/event-stream' }, body: sse },
])

const api = createHttp({ baseUrl: 'https://api.test', use: [mock.middleware] })

// a POST with a JSON body, middleware (this mock, or your auth) and headers: none of which EventSource can do
const chat = api.endpoint('POST /chat', { responseType: 'stream' })
const stream = openEventStream(
  (ctx) => chat({ json: { prompt: 'Say hello' }, signal: ctx.signal, headers: ctx.headers }),
  { reconnect: false },
)

let reply = ''
for await (const ev of stream) {
  if (ev.type === 'done') break
  reply += (ev.data as { text: string }).text
}
console.log(reply) // 'Hello'

import { createHttp } from '@pyreon/http'
import { standardSchema } from '@pyreon/http/schema'
import { For } from '@pyreon/core'
import { useMutation, useQuery } from '@pyreon/query'
import { s } from '@pyreon/validate'

const Todo = s.object({ id: s.number(), title: s.string() })
const api = createHttp({ baseUrl: 'https://app.example.com/api', schema: standardSchema })

const listTodos = api.endpoint('GET /todos', { response: s.array(Todo) })
const addTodo = api.endpoint('POST /todos', { response: Todo })

function Todos() {
  const todos = useQuery(() => listTodos.query()) // key, fn and type from one line
  const add = useMutation({
    mutationFn: (title: string) => addTodo({ json: { title } }),
    invalidates: [listTodos.key.prefix], // every listTodos query refetches
  })

  return (
    <>
      <button onClick={() => add.mutate('Ship it')}>Add</button>
      <ul>
        <For each={() => todos.data() ?? []} by={(t) => t.id}>
          {(t) => <li>{t.title}</li>}
        </For>
      </ul>
    </>
  )
}
